-- RD-95: cobertura "?" dos campos NOVOS do Meu painel de vendas v5 (/dashboard/comercial/meu-painel).
-- O v5 passa a consumir fn_bi_comercial_base + motor-v5 (índice de preço produto a produto, segmentos de cliente,
-- curva ABC, devoluções, a engrenagem "o que entra na análise") — conceitos que a versão anterior não tinha.
-- Aditiva e idempotente (ON CONFLICT DO NOTHING): só ACRESCENTA 9 chaves de ajuda; as demais com.painel.* já existem.
-- Não altera dado de cliente. Linguagem do usuário (RD-95), sem nome de sistema de terceiros (RD-100).
-- Code: dev7claudeps
INSERT INTO public.erp_ajuda_campo (chave, grupo, rotulo, o_que_preencher, para_que_serve, exemplo, erro_comum, ordem, rota, vertical, status)
SELECT v.chave, 'Meu painel de vendas', v.rotulo, v.o_que, v.para_que, v.exemplo, v.erro, v.ordem, '/dashboard/comercial/meu-painel', 'comercial', 'publicado'
FROM (VALUES
 ('com.painel.analise', 'O que entra na análise', 'Indicador calculado — ajuste pela engrenagem, não se digita.', 'Escolhe o que o painel considera no preço e no R$/kg: por padrão o despojo (não-carne) fica de fora. Dá para tirar um corte só do preço médio ou de todo o painel.', 'Tirar "Sebo" e "Couro" do preço médio para o R$/kg refletir só a carne.', 'Deixar o despojo dentro do preço médio: o R$/kg cai sem ser a realidade da carne.', 30),
 ('com.painel.indice', 'Índice de preço', 'Indicador calculado — não se preenche.', 'Compara o preço praticado com a média da empresa no MESMO produto. 100 = na média; acima vendeu mais caro; abaixo mais barato. Compara produto a produto, sem efeito de mix.', 'Índice 92 = em média vendeu 8% abaixo do preço que a empresa pratica naqueles cortes.', 'Ler o índice como desconto: ele já neutraliza o mix; não é o mesmo que o % de desconto na tabela.', 31),
 ('com.painel.segmento', 'Segmento do cliente', 'Indicador calculado — não se preenche.', 'Classifica o cliente pela recência e frequência de compra: Campeões, Fiéis, Novos, Ocasionais, Em risco e Sumindo. Mostra quem sustentar e quem resgatar.', 'Cliente "Em risco": comprava toda semana e sumiu há mais de duas — hora de ligar.', 'Tratar "Sumindo" como perda: muitas vezes é só falta de contato recente.', 32),
 ('com.painel.curva', 'Curva ABC', 'Indicador calculado — não se preenche.', 'Ordena os clientes pelo faturamento acumulado: A = os que somam até 80% do total, B = até 95%, C = o restante. Mostra onde está a concentração.', 'Poucos clientes A respondem pela maior parte do faturamento — perder um pesa muito.', 'Dar o mesmo tratamento a clientes A e C: o esforço precisa seguir a curva.', 33),
 ('com.painel.devolucao', 'Devoluções', 'Indicador calculado — não se preenche.', 'Soma o valor devolvido no período (por vendedor, cliente ou produto) e compara com o faturado para mostrar o peso da devolução.', 'Devoluções de 1,8% do faturado concentradas num produto apontam problema de qualidade ou de pedido.', 'Esquecer a devolução ao olhar o faturamento: ela reduz o resultado real.', 34),
 ('com.painel.prazo', 'Prazo médio', 'Indicador calculado — não se preenche.', 'Prazo médio de pagamento das notas, ponderado pelo valor. Quanto maior, mais tempo o dinheiro leva para entrar.', 'Prazo médio de 28 dias: o vendedor negocia prazos mais longos que a média.', 'Comparar prazo entre vendedores sem olhar o valor: a ponderação já leva o peso de cada nota.', 35),
 ('com.painel.participacao', 'Participação', 'Indicador calculado — não se preenche.', 'O quanto esta linha representa do faturamento total do recorte escolhido.', 'Um cliente com 12% de participação é quem mais pesa na praça.', 'Somar participações de recortes diferentes: cada aba usa o total do seu próprio recorte.', 36),
 ('com.painel.ticket', 'Ticket médio', 'Indicador calculado — não se preenche.', 'Faturamento dividido pelo número de notas: o valor médio de cada pedido.', 'Ticket médio de R$ 3.200 por nota no período.', 'Confundir ticket médio com preço por kg: um é por nota, o outro por quilo.', 37),
 ('com.painel.frequencia', 'Frequência', 'Indicador calculado — não se preenche.', 'Em quantos dias diferentes o cliente comprou no período. Junto com a recência, define o segmento.', 'Frequência 9 = comprou em nove dias distintos no período.', 'Confundir frequência (dias com compra) com número de notas: um cliente pode ter várias notas no mesmo dia.', 38)
) AS v(chave, rotulo, o_que, para_que, exemplo, erro, ordem)
ON CONFLICT (chave) DO NOTHING;
